-- nrd-03-slice-declare-plan.commit.sql
--
-- ============================== COMMIT - THIS WRITES ==============================
-- Byte-identical to the preflight twin except this banner and the terminal statement:
-- COMMIT TRANSACTION here, ROLLBACK TRANSACTION there. Run the preflight first.
--
-- WHAT THIS ADDS: the plan of flight nerdery-citizen-slice-declare (work class owner-objective) under planner agent claude-code-opus-5-5-nerdery-slice, through the
-- installed writer evidence.upsert_flight_plan. It approves nothing and flies nothing. Re-running is harmless.
-- OV3 flies 16 steps: for each of the eight capabilities it declares the DSL (capability-from-dsl) and reads the declared
-- feature pin back. The plan is nerdery/flights/slice-declare.steps.json; its digest is sha256:d651f4fbd376338b2ca2ef41f4d42de63c23c8ef0f0f21e05775d6100c4d8dcd.
-- RUN nrd-02 FIRST, and Part 3 of the DSL work (the check must be installed).
-- WHERE: the sfx-identity database. GUARD: the writer has its four parameters and the owner principal is active.
-- RESULT SETS: guard; plans (plan_revision, matches_reviewed_file 1).
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @params int=(SELECT COUNT(*) FROM sys.parameters WHERE object_id=OBJECT_ID(N'evidence.upsert_flight_plan') AND name IN (N'@principal_id',N'@agent_id',N'@objective',N'@steps_json'));
DECLARE @active int=(SELECT COUNT(*) FROM [identity].principal WHERE principal_id='565de6d4-ebcd-408b-9359-04d21dc62183' AND active=1);
SELECT N'guard' AS result_set,@params AS writer_parameters,4 AS expected_parameters,@active AS owner_principal_active;
IF @params<>4 OR @active<>1
BEGIN
 RAISERROR(N'NRD03_PLAN_GUARD: the plan writer or the owner principal is not as reviewed; nothing was recorded.',16,1);
 ROLLBACK TRANSACTION;
 SET NOEXEC ON;
END
GO
